ALTER TABLE product_variants ADD COLUMN supply_code text NOT NULL DEFAULT 'standard-30', ADD COLUMN version integer NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX variant_supply ON product_variants(product_id,supply_code);
INSERT INTO product_variants(product_id,sku,title,supply_code,currency)
 SELECT product_id,sku||'-60',title||' — 60-day supply','reserve-60',currency FROM product_variants WHERE supply_code='standard-30';
ALTER TABLE carts ADD COLUMN version integer NOT NULL DEFAULT 0, ADD COLUMN merged_into uuid REFERENCES carts(id), ADD COLUMN merged_at timestamptz, ADD CHECK(state IN ('active','merged','expired'));
CREATE TABLE cart_operations(cart_id uuid REFERENCES carts(id),operation_id uuid,request_hash text NOT NULL,result_version integer NOT NULL,PRIMARY KEY(cart_id,operation_id));
CREATE TABLE cart_merge_receipts(source_id uuid PRIMARY KEY REFERENCES carts(id),destination_id uuid NOT NULL REFERENCES carts(id),user_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),phone text NOT NULL DEFAULT '',phone_verified_at timestamptz,contact_email_verified_at timestamptz,version integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_preferences(user_id uuid PRIMARY KEY REFERENCES users(id),locale text NOT NULL DEFAULT 'en-IN' CHECK(locale='en-IN'),reduced_motion boolean NOT NULL DEFAULT false,marketing_email boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),label text NOT NULL,recipient text NOT NULL,phone text NOT NULL,line1 text NOT NULL,line2 text NOT NULL DEFAULT '',landmark text NOT NULL DEFAULT '',city text NOT NULL,region text NOT NULL,postal_code text NOT NULL,country_code text NOT NULL DEFAULT 'IN' CHECK(country_code='IN'),version integer NOT NULL DEFAULT 0,archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,id));
CREATE INDEX addresses_owner ON addresses(user_id,id) WHERE archived_at IS NULL;
CREATE TABLE customer_defaults(user_id uuid PRIMARY KEY REFERENCES users(id),shipping_address_id uuid,billing_address_id uuid,FOREIGN KEY(user_id,shipping_address_id) REFERENCES addresses(user_id,id),FOREIGN KEY(user_id,billing_address_id) REFERENCES addresses(user_id,id));
CREATE TABLE contact_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),email text NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE TABLE privacy_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('export','deletion')),status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','processing','completed','rejected')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_intents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),capability_hash text NOT NULL,mode text NOT NULL CHECK(mode IN ('buy_now','cart')),variant_id uuid REFERENCES product_variants(id),quantity integer CHECK(quantity BETWEEN 1 AND 99),cart_id uuid REFERENCES carts(id),cart_version integer,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 minutes',created_at timestamptz NOT NULL DEFAULT now(),CHECK((mode='buy_now' AND variant_id IS NOT NULL AND quantity IS NOT NULL) OR (mode='cart' AND variant_id IS NULL)));
ALTER TABLE oauth_transactions ADD COLUMN purchase_intent_id uuid REFERENCES purchase_intents(id),ADD COLUMN return_path text NOT NULL DEFAULT '/account',ADD COLUMN reauth_user_id uuid REFERENCES users(id);
CREATE TABLE checkout_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),intent_id uuid UNIQUE NOT NULL REFERENCES purchase_intents(id),mode text NOT NULL CHECK(mode IN ('buy_now','cart')),cart_id uuid REFERENCES carts(id),items jsonb NOT NULL,shipping_address jsonb,billing_address jsonb,version integer NOT NULL DEFAULT 0,quote jsonb,quote_expires_at timestamptz,state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','ordered')),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 minutes',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commerce_settings(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),enabled boolean NOT NULL DEFAULT false,shipping_minor bigint CHECK(shipping_minor>=0),tax_basis_points integer CHECK(tax_basis_points BETWEEN 0 AND 10000),postal_prefixes text[] NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 0);
INSERT INTO commerce_settings DEFAULT VALUES;
CREATE TABLE inventory(variant_id uuid PRIMARY KEY REFERENCES product_variants(id),on_hand integer NOT NULL DEFAULT 0,reserved integer NOT NULL DEFAULT 0,CHECK(on_hand>=reserved AND reserved>=0));
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_reference text UNIQUE NOT NULL,user_id uuid NOT NULL REFERENCES users(id),checkout_id uuid UNIQUE NOT NULL REFERENCES checkout_sessions(id),email_snapshot text NOT NULL,shipping_address jsonb NOT NULL,billing_address jsonb NOT NULL,currency text NOT NULL CHECK(currency='INR'),subtotal_minor bigint NOT NULL CHECK(subtotal_minor>=0),shipping_minor bigint NOT NULL CHECK(shipping_minor>=0),tax_minor bigint NOT NULL CHECK(tax_minor>=0),total_minor bigint NOT NULL CHECK(total_minor=subtotal_minor+shipping_minor+tax_minor),payment_status text NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','paid','expired','refund_pending','refunded','review')),fulfillment_status text NOT NULL DEFAULT 'unfulfilled',cart_consumed_at timestamptz,expires_at timestamptz NOT NULL DEFAULT now()+interval '20 minutes',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_customer ON orders(user_id,created_at DESC,id DESC);
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),variant_id uuid NOT NULL REFERENCES product_variants(id),sku_snapshot text NOT NULL,title_snapshot text NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 99),unit_price_minor bigint NOT NULL CHECK(unit_price_minor>=0));
CREATE TRIGGER immutable_order_item BEFORE UPDATE OR DELETE ON order_items FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TABLE stock_reservations(order_id uuid REFERENCES orders(id),variant_id uuid REFERENCES product_variants(id),quantity integer NOT NULL CHECK(quantity>0),state text NOT NULL CHECK(state IN ('active','released','consumed')),PRIMARY KEY(order_id,variant_id));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid UNIQUE NOT NULL REFERENCES orders(id),provider_order_id text UNIQUE,provider_payment_id text UNIQUE,state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','creating','ready','ambiguous','captured','review')),last_checked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_events(event_id text PRIMARY KEY,payload_hash text NOT NULL,payment_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_id uuid NOT NULL REFERENCES payments(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),request_key uuid NOT NULL UNIQUE,provider_refund_id text UNIQUE,state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','pending','processed','failed','review')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX checkout_owner ON checkout_sessions(user_id,id);
CREATE INDEX payment_pending ON payments(last_checked_at) WHERE state IN ('ready','ambiguous','creating');
